<script setup>defineProps({segments:{default:()=>[]},label:{default:'Avance'},caption:String});const colors={complete:'var(--progress-complete)',partial:'var(--progress-partial)',adapted:'var(--progress-adapted)',resumed:'var(--progress-resumed)',paused:'var(--progress-paused)',postponed:'var(--progress-postponed)',skipped:'var(--progress-skipped)',none:'var(--progress-none)',pending:'var(--progress-none)',started:'var(--progress-none)'};function height(state){if(state==='skipped'||state==='none')return 6;if(state==='partial')return 12;if(state==='paused')return 8;return 22}</script>
<template><div class="nonlinear"><div class="nonlinear__head"><span>{{label}}</span><small v-if="caption">{{caption}}</small></div><div class="nonlinear__bars" role="img" :aria-label="caption||label"><i v-for="(segment,index) in segments" :key="index" :title="segment.title" :class="{'is-started':segment.state==='started'}" :style="{background:colors[segment.state]||'var(--progress-none)',height:`${height(segment.state)}px`}"/></div></div></template>
<style scoped>.nonlinear{display:flex;flex-direction:column;gap:8px}.nonlinear__head{display:flex;align-items:baseline;justify-content:space-between}.nonlinear__head span{color:var(--text-muted);font:600 12px/1 var(--font-core);letter-spacing:.06em;text-transform:uppercase}.nonlinear__head small{color:var(--text-secondary);font:400 13px/1 var(--font-core)}.nonlinear__bars{display:flex;height:22px;align-items:flex-end;gap:3px}.nonlinear__bars i{display:block;min-width:3px;flex:1;border-radius:3px;transition:background var(--dur-base) var(--ease-calm)}.nonlinear__bars i.is-started{border:1.5px solid var(--border-accent)}</style>
